import math

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_to_the_12(n):
    if n == 1:
        return 1

    factors = get_prime_factorization(n)

    tau_val = 1
    for prime, exponent in factors.items():
        # If n = p_1^a_1 * ... * p_k^a_k, then n^12 = p_1^(12a_1) * ... * p_k^(12a_k)
        # tau(n^12) = (12a_1 + 1) * ... * (12a_k + 1)
        tau_val *= (12 * exponent + 1)
    return tau_val

solutions = []
for n in range(1, 101):
    tau_val = tau_n_to_the_12(n)
    if n == tau_val:
        solutions.append(n)

