import math

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_12(n):
    if n == 1:
        return 1
    factors = get_prime_factorization(n)
    tau = 1
    for exponent in factors.values():
        tau *= (12 * exponent + 1)
    return tau

solutions = []
for n in range(1, 101):
    if n == tau_n_12(n):
        solutions.append(n)

